def th(c):
    return c.replace('{own}', 'their own').replace('{self}', 'themselves').replace('{they}', 'they').replace('{them}', 'them')
def yo(c):
    return c.replace('{own}', 'your own').replace('{self}', 'yourself').replace('{they}', 'you').replace('{them}', 'you')

def oitem(i, domain, verbs, about, c, q, fw=('4.15.b7', 'strand:thinking'), rel='the threshold lists 4.4 and 4.5', theme=None):
    stem = i.split('.b')[0]
    L = LISTS[stem]
    fheq, strand = fw
    extra = '' if L['force'] == 'will' else " (the issuer says 'may')"
    s(i, type='outcome', rung='none', force=L['force'], level='fheq:6', appliesTo='graduates of the subject', addressee='learner',
      verbs=verbs, about=about, domain=domain, award=HON,
      para=L['para'].format(c=th(c)), prac=L['prac'].format(c=th(c)), ben=L['ben'].format(c=yo(c)),
      aaw=(f"Treat this as an outcome in the subject's purposes ({L['name']}, section 1), outside the rungs: graduates {L['mod']} show it, "
           f"at FHEQ Level 6 (FQHEIS Level 10) for the honours degree. Cite it as {CITE}, para {stem}. "
           f"Do not present it as a threshold standard or as required of every graduate{extra}. "
           f"Set it beside {rel}, the FHEQ honours descriptor qaa/fheq-2024/{fheq} and the reference framework's {strand} at spine:6."),
      aad=(f"Raise it when {L['when']}. Put it plainly, in the second person, to a student, and as a course design aim to staff. "
           f"Ask: '{q}' Do not read the issuer's list aloud or present it as a pass requirement."))
    if theme:
        TH[i] = theme

