# ---- section 4: the three rungs
LISTNAME = {'4.4': 'threshold level, subject knowledge and skills', '4.5': 'threshold level, generic skills',
            '4.7': 'typical level, subject knowledge and skills', '4.8': 'typical level, generic skills',
            '4.9': 'excellent level, subject knowledge and skills', '4.10': 'excellent level, generic skills'}
FORCE = {'4.4': 'threshold', '4.5': 'threshold', '4.7': 'should', '4.8': 'should', '4.9': 'should', '4.10': 'will'}
RUNG = {'4.4': 'threshold', '4.5': 'threshold', '4.7': 'typical', '4.8': 'typical', '4.9': 'excellent', '4.10': 'excellent'}
UP = {}; DOWN = {}

def ritem(i, verbs, c, q, about, domain, fw, n):
    stem = i.split('.b')[0]
    rung = RUNG[stem]; force = FORCE[stem]
    fheq, ann, strand = fw
    ln = f"{LISTNAME[stem]}, item {n}"
    up = UP.get(i); down = DOWN.get(i)
    if rung == 'threshold':
        para = f"As the minimum for the honours degree, the graduate can {th(c)}."
        prac = f"Threshold: plan teaching and assessment so that every honours graduate can {th(c)}; this is the floor for the award."
        ben = f"By the end of your honours degree you will, at the least, be able to {yo(c)}."
        aaw = (f"Treat this as a threshold standard: the least an honours graduate in the subject will have shown on {about}, at FHEQ Level 6 (FQHEIS Level 10). "
               f"Cite it as {CITE}, para {stem} ({ln}). Do not call it a regulatory requirement or claim it holds at another level. "
               f"Set it beside {R(up)} at the typical level, the FHEQ honours descriptor qaa/fheq-2024/{fheq} and Annex D's qaa/fheq-2024/annex-d/{ann}/3rd (spine:6, {strand}).")
        aad = (f"Raise it when a student asks what they must at least be able to do on {about}, or when a programme team checks a module against the threshold. "
               f"Put it in plain words, in the second person, to a student, and as the floor the course must evidence to staff. "
               f"Ask: '{q}' Do not read the list aloud or offer the typical or excellent level as the pass standard.")
        extra = dict(forceFrom='4.1')
    elif rung == 'typical':
        para = f"At the typical level, above the minimum, the graduate should be able to {th(c)}."
        prac = f"Typical level: design for most students to be able to {th(c)}, beyond the threshold for the award."
        ben = f"To work at the typical level of your honours degree, you should be able to {yo(c)}."
        aaw = (f"Treat this as a typical-level standard (should): what most honours graduates show on {about}, above the threshold, at FHEQ Level 6 (FQHEIS Level 10). "
               f"Cite it as {CITE}, para {stem} ({ln}). Do not present it as the minimum for the award or as a regulatory requirement. "
               f"Set it beside {R(down)} (threshold), {R(up)} (excellent), qaa/fheq-2024/{fheq} and Annex D's qaa/fheq-2024/annex-d/{ann}/2.1, a match we infer (spine:6, {strand}).")
        aad = (f"Raise it when a student who meets the minimum on {about} asks how to do well, or when staff set marking criteria for the middle of the range. "
               f"Present it as a step above the threshold, plainly to a student and as a design aim to staff. "
               f"Ask: '{q}' Avoid treating it as the minimum or reading the issuer's list aloud.")
        extra = {}
    else:
        md = 'should' if force == 'should' else 'will'
        para = f"At the excellent level the graduate {md} be able to {th(c)}."
        prac = f"Excellent level: set tasks that let the strongest students {th(c)}; this describes the top of the range, not the pass standard."
        ben = f"If you reach the excellent level in your honours degree, you {md} be able to {yo(c)}."
        aaw = (f"Treat this as an excellent-level standard ({force}): the top of the range for honours graduates on {about}, at FHEQ Level 6 (FQHEIS Level 10), not a requirement for the award. "
               f"Cite it as {CITE}, para {stem} ({ln}). Do not present it as the pass standard or as a master's outcome. "
               f"Set it beside {R(down)} at the typical level, the FHEQ honours descriptor qaa/fheq-2024/{fheq} and Annex D's qaa/fheq-2024/annex-d/{ann}/1st (spine:6, {strand}).")
        aad = (f"Raise it when a strong student asks what outstanding work on {about} looks like, or when staff write criteria for the top marks. "
               f"Present it as an aim, never a requirement: in plain words to a student and as a stretch goal to staff. "
               f"Ask: '{q}' Avoid implying that a student fails without it.")
        extra = {}
    s(i, type=rung, rung=rung, force=force, level='fheq:6', appliesTo='honours graduates of the subject', addressee='learner',
      verbs=verbs, about=about, domain=domain, award=HON, para=para, prac=prac, ben=ben, aaw=aaw, aad=aad, **extra)

def row(name, domain, fw, t, ty, ex, ths=None):
    """t, ty, ex: (id, verbs, c, q). ty may be a list (two typical items for one outcome)."""
    tys = ty if isinstance(ty, list) else [ty]
    for x in tys:
        DOWN[x[0]] = t[0]
        UP[x[0]] = ex[0]
        GRADE[x[0]] = t[0]
    UP[t[0]] = tys[0][0]
    DOWN[ex[0]] = tys[-1][0]
    GRADE[ex[0]] = tys[-1][0]
    for x in [t] + tys + [ex]:
        ritem(x[0], x[1], x[2], x[3], name, domain, fw, x[0].split('.b')[1])
        if ths:
            TH[x[0]] = ths
    for k, x in enumerate(tys):
        OUTCOMES.append(dict(outcome=name if len(tys) == 1 else f"{name} ({'interrogate' if k == 0 else 'critique'})",
                             threshold=t[0], typical=x[0], excellent=ex[0], basis='inferred', domain=domain, award=HON))

