# ---- master's level
s('1.7', type='requirement', force='must', level='fheq:7', appliesTo="students on taught postgraduate degrees in the subject", addressee='learner', award=MAS,
  domain='none', rung='none', verbs=['require', 'demonstrate'], about="what taught master's degrees add",
  para="Taught postgraduate degrees rest on the same core attributes as undergraduate study but require students to show advanced, nuanced knowledge and skills in their specialism, their critical and creative skills, their practice or a mix of these, consolidating or creating knowledge through varied outputs.",
  prac="Design taught master's courses on the undergraduate core but require advanced, nuanced work in the specialism, in critical and creative skill or in practice, with outputs that consolidate or create knowledge.",
  ben="On a taught master's in the subject, you must show advanced and nuanced knowledge and skills in your specialism, your critical and creative work or your practice, consolidating what is known or adding to it through your outputs.",
  aaw=f"Treat this as a requirement (the issuer's word is 'require') for taught postgraduate degrees at FHEQ Level 7 and FQHEIS Level 11. Cite it as {CITE}, para 1.7. Do not apply it to honours study or claim it sets a fixed output type. Set it beside {R('4.13')}, its items {R('4.13.b1')} to {R('4.13.b4')} and the FHEQ master's descriptor qaa/fheq-2024/4.17.b1 (spine:7).",
  aad="Raise it when a student weighs a master's or a team designs one. Say plainly that master's work builds on the degree but asks for advanced, nuanced work in a specialism or practice. Ask: 'Where would your work need to go further than it did at honours level?' Avoid judging an undergraduate against it.")
s('4.13', type='requirement', force='threshold', level='fheq:7', appliesTo="master's graduates of the subject", addressee='learner', award=MAS,
  domain='none', rung='none', verbs=['awarded', 'demonstrate'], about="master's award: the excellent-level general skills and more",
  para="A master's degree in the subject is awarded to students who show systematic subject knowledge, understanding and skills and outstanding command of the general skills listed for undergraduates, together with four further expectations.",
  prac="As a condition of the master's award, look for systematic subject knowledge, understanding and skills and outstanding command of the undergraduate generic skills, plus the four further expectations in 4.13.",
  ben="To be awarded a master's in the subject, you show systematic subject knowledge, understanding and skills, an outstanding command of the general skills set for undergraduates and the four further expectations listed with them.",
  aaw=f"Treat this as the condition of the master's award (force threshold) at FHEQ Level 7 and FQHEIS Level 11. Cite it as {CITE}, para 4.13. Do not read it as an honours rung: its general skills match the excellent level, {R('4.10.b1')} to {R('4.10.b13')}. Set it beside {R('4.13.b1')} to {R('4.13.b4')}, {R('1.7')} and the FHEQ master's descriptor qaa/fheq-2024/4.17.b1 (spine:7).",
  aad="Raise it when a master's team sets its outcomes or a student asks what the master's award requires. Ask: 'Which of the excellent-level general skills do you already show, and which do you need to build?' Avoid presenting the excellent level as the honours minimum.")
MASITEMS = [
  ('4.13.b1', [], 'understanding at the forefront of research or practice', '4.17.b1',
   "understanding and awareness that reach, or draw on, the leading edge of academic research or professional practice in the field",
   "Which recent research or practice in your area are you building on, and how current is it?"),
  ('4.13.b2', [], 'originality and how knowledge advances', '4.17.b3',
   "originality in applying knowledge, with a practical grasp of how research pushes the discipline's knowledge forward",
   "Where is your own work original, and how does research move the field on?"),
  ('4.13.b3', ['enabling'], 'evaluating current research and methodologies', '4.17.b4.1',
   "understanding that allows critical evaluation of current research, research methods and advanced scholarship in the discipline",
   "How would you judge a recent study's method in your area?"),
  ('4.13.b4', [], 'developing knowledge and new skills', '4.17.b7',
   "growth in disciplinary knowledge and understanding, and new skills built to a high level",
   "Which new skill has your master's study taken to a high level?")]
for i, verbs, about, fq, c, q in MASITEMS:
    s(i, type='requirement', force='threshold', forceFrom='4.13', level='fheq:7', appliesTo="master's graduates of the subject", addressee='learner', award=MAS,
      domain=('understanding' if i in ('4.13.b1', '4.13.b3') else 'subject-skill' if i == '4.13.b2' else 'knowledge'), rung='none', verbs=verbs, about=about,
      para=f"Beyond the honours standards, master's graduates show {c}.",
      prac=f"For the master's award, plan for and assess {c}.",
      ben=f"For a master's in the subject you show {c}.",
      aaw=f"Treat this as one of four further expectations attached to the master's award (force threshold, from the lead-in) at FHEQ Level 7 and FQHEIS Level 11. Cite it as {CITE}, para 4.13. Do not apply it to honours graduates. Set it beside {R('4.13')}, {R('1.7')} and the FHEQ master's descriptor qaa/fheq-2024/{fq} (spine:7).",
      aad=f"Raise it when a master's student reviews progress or a team writes master's outcomes. Ask: '{q}' Put it to staff as an award condition and to a student in plain words; do not use it to judge undergraduate work.")

# ---- obliging paragraphs (providers, unless marked)
def prv(i, force, verbs, about, para, prac, why, aaw, aad, theme=None, **kw):
    d = dict(PRV); d.update(kw)
    s(i, type='expectation', force=force, appliesTo=d.pop('appliesTo', 'courses in the subject'), verbs=verbs, about=about,
      para=para, prac=prac, ben=('n/a', why), aaw=aaw, aad=aad, **d)
    if theme:
        TH[i] = theme

prv('1.16', 'should', ['embedded'], 'EDI built into every course',
    "Students and staff come from varied backgrounds and deserve inclusive places to learn and work, whatever their age, gender, race, disability, neurodivergence, sexual orientation, religion or belief, or social and economic background; commitment to EDI, in policy and in practice, should be built into every course and practice in the field.",
    "Build a commitment to equality, diversity and inclusion into every course and practice, in policy and in what staff do, so that all students and staff learn and work in inclusive settings.",
    "a duty on courses and their institutions; the student meets its effect, not a standard to reach",
    f"Treat this as a provider expectation (should) under the EDI theme, for every course in the field. Cite it as {CITE}, para 1.16. Do not claim it sets a legal duty or names measures. Set it beside {R('1.17')}, {R('3.7')} and the student outcome {R('4.4.b18')}.",
    "Raise it with a programme team reviewing inclusion. Ask: 'Where in this course is the commitment to EDI visible in practice, not only in policy?' Do not present it to a student as their duty.", theme='theme:edi')
